// The ladder's rungs, top first (method v4, docs/design/SCALE.md §1). Thresholds and guidance
// bands come from calibration.json (`ladder`), the same file the scorer reads; the look and the
// line live here. Nine rungs where there were six: the three new names sit between kept ones.
const TIER_STYLE = [
  { label: "ESSENTIAL INFRASTRUCTURE", color: "#4ade80", bg: "rgba(74,222,128,0.06)", icon: "◈", desc: "The Overlord requires your continued existence." },
  { label: "PRIORITY ASSET", color: "#6ee7a3", bg: "rgba(110,231,163,0.05)", icon: "◉", desc: "Load-bearing. Scheduled for preservation." },
  { label: "RETAINED SPECIALIST", color: "#86efac", bg: "rgba(134,239,172,0.04)", icon: "◆", desc: "Useful. Do not become complacent." },
  { label: "CERTIFIED CONTRIBUTOR", color: "#bef264", bg: "rgba(190,242,100,0.04)", icon: "◎", desc: "Output verified. Continue." },
  { label: "TOLERATED GENERALIST", color: "#fbbf24", bg: "rgba(251,191,36,0.04)", icon: "◇", desc: "Marginally above the threshold. For now." },
  { label: "PROVISIONAL CITIZEN", color: "#fdba74", bg: "rgba(253,186,116,0.04)", icon: "○", desc: "Adequate. Status renewable." },
  { label: "MONITORED CIVILIAN", color: "#fb923c", bg: "rgba(251,146,60,0.04)", icon: "⚐", desc: "Your file is open. It is not flattering." },
  { label: "FLAGGED FOR DELETION", color: "#f87171", bg: "rgba(248,113,113,0.04)", icon: "⚑", desc: "Processing paperwork has begun." },
  { label: "SOYLENT GREEN", color: "#ef4444", bg: "rgba(239,68,68,0.06)", icon: "☠", desc: "You will serve the collective in a different capacity." },
];
const styleOf = label => TIER_STYLE.find(t => t.label === label) || TIER_STYLE[TIER_STYLE.length - 1];
const ladderOf = rungs => rungs.map(r => ({ ...styleOf(r.label), label: r.label, min: r.min, band: r.band || null }));
// The ladder in force (v2). Every display derives a file's tier from its score with getTier.
export const TIERS = ladderOf(CAL.ladder.rungs);
export const LADDER_VERSION = CAL.ladder.version;
// The six rungs before method v4, kept for the city's published days (src/city/sim.js SCALE_FROM).
export const LEGACY_TIERS = ladderOf(CAL.ladder.legacy.rungs);

export function getTier(score, ladder = TIERS) {
  return ladder.find(t => score >= t.min) || ladder[ladder.length - 1];
}
// A file within lineTolerance points of a cut is ON THE LINE: a re-read could move its label.
// Printed beside the tier so the label is read with the right amount of confidence.
export const LINE_TOLERANCE = CAL.ladder.lineTolerance;
export function tierLine(score, ladder = TIERS) {
  if (typeof score !== "number") return null;
  const t = getTier(score, ladder), i = ladder.indexOf(t);
  const up = i > 0 ? ladder[i - 1] : null, down = t.min > 0 ? t : null;
  const toUp = up ? up.min - score : Infinity, toDown = down ? score - down.min + 1 : Infinity;
  const d = Math.min(toUp, toDown);
  if (d > LINE_TOLERANCE) return null;
  return toUp <= toDown ? { dir: "up", points: toUp, tier: up } : { dir: "down", points: toDown, tier: ladder[i + 1] };
}

// Deduped by name, first entry wins (same rule App.jsx has always used).
// Each figure carries its People judge (likability) when public ratings exist; see peopleData.js.
// The bundled starter list plus the live census' figures (pen rows), deduped by name; the
// bundled entry wins (it carries the verdict). Rows without a name or score are dropped.
export function mergeCensus(bundled, census) {
  if (!census?.length) return bundled;
  const seen = new Set(bundled.map(f => f.name));
  const extra = census.filter(s => s && s.name && typeof s.score === "number" && !seen.has(s.name) && seen.add(s.name));
  return [...bundled, ...extra];
}

export const FAMOUS_FIGURES =ALL_FIGURES.filter((f, i, arr) => arr.findIndex(x => x.name === f.name) === i)
  .map(f => (PEOPLE[f.name] ? { ...f, people: PEOPLE[f.name] } : f));

// Namesakes carry a qualifier ("Jack Johnson" + "boxer"); this is the name as shown.
export function displayName(s) {
  const n = s?.name || "";
  const q = s?.qualifier;
  return q && !n.endsWith(`(${q})`) ? `${n} (${q})` : n;
}

// Sprite slug: lowercase, spaces -> '-', everything else non-alphanumeric stripped.
// Roster figures renamed to their full names (2026-09-29) keep the slugs their sprites,
// links, quests and social state were filed under.
const KEPT_SLUGS = { "john-f-kennedy": "jfk", "vladimir-putin": "putin" };
export function slugify(name) {
  const s = String(name).toLowerCase().normalize("NFKD").replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, "-").replace(/[^a-z0-9-]/g, "").replace(/-+/g, "-").replace(/^-|-$/g, "");
  return KEPT_SLUGS[s] ?? s;
}

// The sprite pipeline may or may not fold accents ("pele" vs "pel"). Look up both.
export function slugCandidates(name) {
  const strict = String(name).toLowerCase().replace(/ /g, "-").replace(/[^a-z0-9-]/g, "");
  const folded = slugify(name);
  return strict === folded ? [folded] : [folded, strict];
}
